  public Car {
    Objects.requireNonNull(props, "props must not be null");
    if (props.containsKey("model") && !(props.get("model") instanceof String))
      throw new IllegalArgumentException("model must be a String");
  }
  @Override public Object get(String key) { return props.get(key); }
}

